            return setTextRange(
                factory.createPropertyAccessExpression(
                    factory.createCallExpression(
                        factory.createIdentifier("_superIndex"),
                        /*typeArguments*/ undefined,
                        [argumentExpression],
                    ),
                    "value",
                ),
                location,
            );
        }
        else {
            return setTextRange(
                factory.createCallExpression(
                    factory.createIdentifier("_superIndex"),
                    /*typeArguments*/ undefined,
                    [argumentExpression],
                ),
                location,
            );
        }
    }
}

