                            finishObjectLiteralIfNeeded();
                            expressions.push(Debug.checkDefined(visitNode(prop.expression, visitor, isExpression)));
                            continue;
                        }
                        properties.push(Debug.checkDefined(visitNode(prop, visitor)) as ObjectLiteralElementLike);
                    }
                    continue;
